diff --git a/shape/budget.go b/shape/budget.go
index f1a7d29..8718fc5 100644
--- a/shape/budget.go
+++ b/shape/budget.go
@@ -48,7 +48,8 @@ func budgetStop(last lastSubmission, answer string, answers int, elapsed time.Du
 	return result
 }

-// timedAttempt is one refused submission: the first refusing gate, the time of the model request
+// timedAttempt is one refused submission, or the last submission when it was checked and not refused:
+// the first refusing gate (or the check that ended an unrefused one), the time of the model request
 // that produced it, the time Kogen spent checking it and the shaping budget left when that check ended.
 type timedAttempt struct {
 	attempt   int
@@ -56,13 +57,14 @@ type timedAttempt struct {
 	model     time.Duration
 	check     time.Duration
 	remaining time.Duration
+	over      time.Duration // how far past the budget the checks ended; set only for an unrefused submission
 }

 // wholeSeconds is a duration in whole seconds, truncated and never below 0.
 func wholeSeconds(d time.Duration) int { return int(max(d, 0) / time.Second) }

 // attemptLines state the shaping budget, as the shaping_turn_counts event records it, and
-// one line per refused submission, oldest first.
+// one line per refused submission and one for the last submission when it was checked without a refusal, oldest first.
 func attemptLines(attempts []timedAttempt, install time.Duration) []string {
 	lines := []string{fmt.Sprintf("shaping budget: %d s (%d min, wall-clock for the whole shaping, all rounds; the response_budget event is the separate limit on one provider response wait)",
 		shapingBudgetSeconds(), int(shapingBudget/time.Minute))}
@@ -72,8 +74,12 @@ func attemptLines(attempts []timedAttempt, install time.Duration) []string {
 	}
 	lines[0] += suffix
 	for _, a := range attempts {
+		over := ""
+		if wholeSeconds(a.over) > 0 {
+			over = fmt.Sprintf(", %d s over", wholeSeconds(a.over))
+		}
 		lines = append(lines, fmt.Sprintf("attempt %d: gate %s, model request %d s, Kogen checks %d s, %d s remaining",
-			a.attempt, a.gate, wholeSeconds(a.model), wholeSeconds(a.check), wholeSeconds(a.remaining))+suffix)
+			a.attempt, a.gate, wholeSeconds(a.model), wholeSeconds(a.check), wholeSeconds(a.remaining))+over+suffix)
 	}
 	return lines
 }

